            array('id' => '8','key' => 'team-section','value' => '{"language":{"en":{"section_title":"Our Team","title":"Meet Our Rj","section_icon":"fas fa-podcast"},"es":{"section_title":"Nuestro equipo","title":"Conozca a nuestro Rj","section_icon":"fas fa-podcast"},"hi":{"section_title":"\\u0939\\u092e\\u093e\\u0930\\u0940 \\u091f\\u0940\\u092e","title":"\\u0939\\u092e\\u093e\\u0930\\u0947 \\u0906\\u0930\\u091c\\u0947 \\u0938\\u0947 \\u092e\\u093f\\u0932\\u0947\\u0902","section_icon":"fas fa-podcast"},"ar":{"section_title":"\\u0641\\u0631\\u064a\\u0642\\u0646\\u0627","title":"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0622\\u0631 \\u062c\\u064a\\u0647 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0646\\u0627","section_icon":"fas fa-podcast"},"fr":{"section_title":"Notre \\u00e9quipe","title":"Rencontrez notre RJ","section_icon":"fas fa-podcast"}},"items":{"6604ffe0e212e":{"language":{"en":{"item_name":"Sarah Summers","item_designation":"Morning Melodies Maestro","item_about":"Sarah Summers is a gifted musician and composer known for her enchanting morning-themed melodies that uplift and inspire. With a deep passion for creating soothing and harmonious tunes, she has earned the title of \\"Morning Melodies Maestro\\" for her ability to transform ordinary mornings into extraordinary experiences through music.\\r\\n\\r\\nWhether performing live, composing original pieces, or mentoring aspiring musicians, Sarah brings warmth and creativity to everything she does. Her work has been featured on numerous platforms, from peaceful morning playlists to wellness retreats, where her melodies set the tone for a perfect start to the day.\\r\\n\\r\\nDriven by her love for music and a desire to connect with people, Sarah Summers continues to inspire audiences worldwide, one melody at a time."},"es":{"item_name":"sara veranos","item_designation":"Melod\\u00edas de la ma\\u00f1ana Maestro","item_about":"Sarah Summers es una talentosa m\\u00fasico y compositora conocida por sus encantadoras melod\\u00edas matutinas que animan e inspiran. Con una profunda pasi\\u00f3n por crear melod\\u00edas relajantes y armoniosas, se ha ganado el t\\u00edtulo de \\"Maestra de las melod\\u00edas matutinas\\" por su capacidad de transformar las ma\\u00f1anas ordinarias en experiencias extraordinarias a trav\\u00e9s de la m\\u00fasica.\\r\\n\\r\\nYa sea tocando en vivo, componiendo piezas originales o asesorando a m\\u00fasicos aspirantes, Sarah aporta calidez y creatividad a todo lo que hace. Su trabajo ha aparecido en numerosas plataformas, desde listas de reproducci\\u00f3n matutinas tranquilas hasta retiros de bienestar, donde sus melod\\u00edas marcan el tono para un comienzo perfecto del d\\u00eda.\\r\\n\\r\\nImpulsada por su amor por la m\\u00fasica y el deseo de conectarse con la gente, Sarah Summers contin\\u00faa inspirando a audiencias de todo el mundo, una melod\\u00eda a la vez."},"hi":{"item_name":"\\u0938\\u093e\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0938","item_designation":"\\u092e\\u0949\\u0930\\u094d\\u0928\\u093f\\u0902\\u0917 \\u092e\\u0947\\u0932\\u094b\\u0921\\u0940\\u091c\\u093c \\u092e\\u0947\\u0938\\u094d\\u091f\\u094d\\u0930\\u094b","item_about":"\\u0938\\u093e\\u0930\\u093e \\u0938\\u092e\\u0930\\u094d\\u0938 \\u090f\\u0915 \\u092a\\u094d\\u0930\\u0924\\u093f\\u092d\\u093e\\u0936\\u093e\\u0932\\u0940 \\u0938\\u0902\\u0917\\u0940\\u0924\\u0915\\u093e\\u0930 \\u0914\\u0930 \\u0938\\u0902\\u0917\\u0940\\u0924\\u0915\\u093e\\u0930 \\u0939\\u0948\\u0902, \\u091c\\u094b \\u0905\\u092a\\u0928\\u0940 \\u092e\\u0928\\u092e\\u094b\\u0939\\u0915 \\u0938\\u0941\\u092c\\u0939-\\u0925\\u0940\\u092e \\u0935\\u093e\\u0932\\u0940 \\u0927\\u0941\\u0928\\u094b\\u0902 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u091c\\u093e\\u0928\\u0940 \\u091c\\u093e\\u0924\\u0940 \\u0939\\u0948\\u0902, \\u091c\\u094b \\u0909\\u0924\\u094d\\u0925\\u093e\\u0928 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u0947\\u0930\\u0923\\u093e \\u0926\\u0947\\u0924\\u0940 \